} from "lucide-react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import * as XLSX from "xlsx";
import { QRCodeCanvas } from "qrcode.react";
import html2canvas from "html2canvas";
import jsPDF from "jspdf";
import Layout from "./Layout";
import logo from "../../assets/logo1.png";

export default function InternsPourSuperadmin() {
  const navigate = useNavigate();
  const [searchQuery, setSearchQuery] = useState("");
  const [interns, setInterns] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [sortField, setSortField] = useState("First_Name");
  const [sortDirection, setSortDirection] = useState("asc");
  const [isDetailsModalOpen, setIsDetailsModalOpen] = useState(false);
  const [isPasswordModalOpen, setIsPasswordModalOpen] = useState(false);
  const [isBadgeModalOpen, setIsBadgeModalOpen] = useState(false);
  const [selectedIntern, setSelectedIntern] = useState(null);
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [passwordError, setPasswordError] = useState("");
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isFlipped, setIsFlipped] = useState(false);
  const [filterSector, setFilterSector] = useState("");
  const [filterYear, setFilterYear] = useState("");

  useEffect(() => {
    fetchInterns();
  }, []);

  const fetchInterns = async () => {
    setIsLoading(true);
    setError("");
    const token = localStorage.getItem("token");

    if (!token) {
      setError("Authentification requise. Veuillez vous connecter.");
      setIsLoading(false);
      return;
    }

    try {
      const response = await axios.get(
        `${process.env.REACT_APP_API_URL}/api/interns?includePassword=true`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
            Role: "Deputydirector",
          },
        }
      );
      if (response.data.success) {
        setInterns(response.data.data || []);
      } else {
        setError(
          "Échec de la récupération des stagiaires : " + response.data.message
        );
      }
    } catch (err) {
      setError(
        `Erreur lors de la récupération des stagiaires : ${
          err.response?.data?.message || err.message
        }`
      );
      /* eslint-disable */console.error(...oo_tx(`3091585745_97_6_97_67_11`,"Erreur de récupération des stagiaires :", err));
    } finally {
      setIsLoading(false);
    }
  };

  const handleSort = (field) => {
    if (sortField === field) {
      setSortDirection(sortDirection === "asc" ? "desc" : "asc");
    } else {
      setSortField(field);
      setSortDirection("asc");
    }
  };

  const handleEditIntern = (id) => {
    navigate(`/EditIntern/${id}`);
  };

  const handleDeleteIntern = async (id) => {
    if (window.confirm("Êtes-vous sûr de vouloir supprimer ce stagiaire ?")) {
      try {
        const token = localStorage.getItem("token");
        await axios.delete(`${process.env.REACT_APP_API_URL}/api/interns/${id}`, {
          headers: {
            Authorization: `Bearer ${token}`,
            Role: "Deputydirector",
          },
        });
        setInterns(interns.filter((intern) => intern._id !== id));
        setError("");
      } catch (err) {
        setError(
          "Échec de la suppression du stagiaire : " +
            (err.response?.data?.message || err.message)
        );
      }
    }
  };

  const handleRemoveInternToFormer = async (id, firstName, lastName) => {
    if (
      window.confirm(
        `Êtes-vous sûr de vouloir retirer ${firstName} ${lastName} de la liste des stagiaires actifs ? Cette action calculera leur paiement total, enregistrera leurs données dans les anciens stagiaires avec la date d'entrée (date de création) et la date de sortie (aujourd'hui), et supprimera leurs données des stagiaires actifs.`
      )
    ) {
      try {
        const token = localStorage.getItem("token");
        const response = await axios.post(
          `${process.env.REACT_APP_API_URL}/api/interns/${id}/remove-to-former`,
          {},
          {
            headers: {
              Authorization: `Bearer ${token}`,
              Role: "Deputydirector",
            },
          }
        );
        if (response.data.success) {
          setInterns(interns.filter((intern) => intern._id !== id));
          setError("");
        } else {
          setError(
            "Échec du déplacement du stagiaire vers anciens stagiaires : " +
              response.data.message
          );
        }
      } catch (err) {
        setError(
          "Échec du déplacement du stagiaire vers anciens stagiaires : " +
            (err.response?.data?.message || err.message)
        );
      }
    }
  };

  const handleCalculateAndResetPayments = async () => {
    if (
      window.confirm(
        "Vous êtes sur le point de calculer le paiement total pour chaque stagiaire et de réinitialiser leurs paiements mensuels à zéro. Cette action mettra à jour le champ 'Total Paiement' pour chaque stagiaire et réinitialisera les montants mensuels dans la collection des paiements. Voulez-vous continuer ?"
      )
    ) {
      try {
        const token = localStorage.getItem("token");
        const response = await axios.post(
          `${process.env.REACT_APP_API_URL}/api/interns/calculate-and-reset-payments`,
          {},
          {
            headers: {
              Authorization: `Bearer ${token}`,
              Role: "Deputydirector",
            },
          }
        );
        if (response.data.success) {
          await fetchInterns();
          setError("");
        } else {
          setError(
            "Échec du calcul et de la réinitialisation des paiements : " +
              response.data.message
          );
        }
      } catch (err) {
        setError(
          "Échec du calcul et de la réinitialisation des paiements : " +
            (err.response?.data?.message || err.message)
        );
      }
    }
  };

  const openDetailsModal = (intern) => {
    setSelectedIntern(intern);
    setIsDetailsModalOpen(true);
    setPasswordError("");
  };

  const closeDetailsModal = () => {
    setIsDetailsModalOpen(false);
    setSelectedIntern(null);
    setIsPasswordModalOpen(false);
    setNewPassword("");
    setConfirmPassword("");
    setPasswordError("");
  };

  const openPasswordModal = () => {
    setIsPasswordModalOpen(true);
    setNewPassword("");
    setConfirmPassword("");
    setPasswordError("");
  };

  const closePasswordModal = () => {
    setIsPasswordModalOpen(false);
    setNewPassword("");
    setConfirmPassword("");
    setPasswordError("");
  };

  const handleUpdatePassword = async () => {
    if (newPassword !== confirmPassword) {
      setPasswordError("Les mots de passe ne correspondent pas.");
      return;
    }

    if (newPassword.length < 6) {
      setPasswordError("Le mot de passe doit contenir au moins 6 caractères.");
      return;
    }

    try {
      const token = localStorage.getItem("token");
      if (!token) {
        setPasswordError("Authentification requise. Veuillez vous connecter.");
        return;
      }

      const response = await axios.put(
        `${process.env.REACT_APP_API_URL}/api/interns/${selectedIntern._id}/password`,
        { password: newPassword },
        {
          headers: {
            Authorization: `Bearer ${token}`,
            Role: "Deputydirector",
          },
        }
      );

      if (response.data.success) {
        setPasswordError("");
        closePasswordModal();
      } else {
        setPasswordError(
          response.data.message || "Échec de la mise à jour du mot de passe."
        );
      }
    } catch (err) {
      /* eslint-disable */console.error(...oo_tx(`3091585745_276_6_276_64_11`,"Erreur côté frontal :", err.response?.data));
      setPasswordError(
        err.response?.data?.message ||
          "Erreur lors de la mise à jour du mot de passe."
      );
    }
  };

  const openBadgeModal = (intern) => {
    setSelectedIntern(intern);
    setIsBadgeModalOpen(true);
    setIsFlipped(false);
  };

  const closeBadgeModal = () => {
    setIsBadgeModalOpen(false);
    setSelectedIntern(null);
  };

  const handleDownloadBadge = () => {
    if (!selectedIntern.image) {
      alert("Image non trouvée");
      return;
    }

    const doc = new jsPDF({
      orientation: "portrait",
      unit: "mm",
      format: "a4",
    });
    const badgeContainer = document.getElementById("badge-container");
    const frontElement = document.getElementById("badge-front");
    const backElement = document.getElementById("badge-back");

    frontElement.style.visibility = "visible";
    backElement.style.visibility = "visible";
    frontElement.style.transform = "none";
    backElement.style.transform = "none";
    badgeContainer.style.transform = "none";

    const imgElement = frontElement.querySelector("img");
    if (!imgElement) {
      /* eslint-disable */console.error(...oo_tx(`3091585745_318_6_318_60_11`,"No image element found in badge-front"));
      alert("Image non trouvée");
      return;
    }

    const captureFront = () => {
      html2canvas(frontElement, {
        scale: 2,
        backgroundColor: "#ffffff",
        logging: true,
        useCORS: true,
      })
        .then((frontCanvas) => {
          /* eslint-disable */console.log(
            ...oo_oo(`3091585745_331_10_335_11_4`,"Front canvas captured, size:",
            frontCanvas.width,
            frontCanvas.height)
          );
          const frontImgData = frontCanvas.toDataURL("image/png");

          html2canvas(backElement, {
            scale: 2,
            backgroundColor: "#ffffff",
            logging: true,
            useCORS: true,
          })
            .then((backCanvas) => {
              /* eslint-disable */console.log(
                ...oo_oo(`3091585745_345_14_349_15_4`,"Back canvas captured, size:",
                backCanvas.width,
                backCanvas.height)
              );
              const backImgData = backCanvas.toDataURL("image/png");

              const pageWidth = doc.internal.pageSize.getWidth();
              const badgeWidth = pageWidth / 2 - 10;
              const badgeHeight =
                (frontCanvas.height * badgeWidth) / frontCanvas.width;

              doc.addImage(frontImgData, "PNG", 5, 20, badgeWidth, badgeHeight);
              doc.addImage(
                backImgData,
                "PNG",
                pageWidth / 2 + 5,
                20,
                badgeWidth,
                badgeHeight
              );

              doc.save(
                `Badge_${selectedIntern.First_Name}_${selectedIntern.Last_Name}.pdf`
              );

              if (isFlipped) {
                frontElement.style.visibility = "hidden";
                backElement.style.visibility = "visible";
                badgeContainer.style.transform = "rotateY(180deg)";
              } else {
                frontElement.style.visibility = "visible";
                backElement.style.visibility = "hidden";
                badgeContainer.style.transform = "rotateY(0deg)";
              }
            })
            .catch((error) => {
              /* eslint-disable */console.error(...oo_tx(`3091585745_382_14_382_59_11`,"Error capturing back:", error));
              alert("Erreur lors de la capture du verso du badge");
            });
        })
        .catch((error) => {
          /* eslint-disable */console.error(...oo_tx(`3091585745_387_10_387_56_11`,"Error capturing front:", error));
          alert("Erreur lors de la capture du recto du badge");
        });
    };

    if (imgElement.complete && imgElement.naturalWidth !== 0) {
      /* eslint-disable */console.log(...oo_oo(`3091585745_393_6_393_61_4`,"Image already loaded, capturing front..."));
      captureFront();
    } else {
      /* eslint-disable */console.log(...oo_oo(`3091585745_396_6_396_49_4`,"Waiting for image to load..."));
      imgElement.onload = () => {
        /* eslint-disable */console.log(...oo_oo(`3091585745_398_8_398_55_4`,"Image loaded, capturing front..."));
        captureFront();
      };
      imgElement.onerror = () => {
        /* eslint-disable */console.error(...oo_tx(`3091585745_402_8_402_62_11`,"Image failed to load:", imgElement.src));
        alert("Image non trouvée");
        frontElement.style.visibility = "visible";
        backElement.style.visibility = "hidden";
        badgeContainer.style.transform = isFlipped
          ? "rotateY(180deg)"
          : "rotateY(0deg)";
      };
      imgElement.src = imgElement.src;
    }
  };

  const handleFlip = () => {
    setIsFlipped(!isFlipped);
  };

  const filteredAndSortedInterns = interns
    .filter((intern) => {
      const firstName = (intern.First_Name || "").toLowerCase();
      const lastName = (intern.Last_Name || "").toLowerCase();
      const cff = (intern.CFF || "").toLowerCase();
      const hometown = (intern.hometown || "").toLowerCase();
      const email = (intern.email || "").toLowerCase();
      const emplacement = (intern.emplacement || "").toLowerCase();
      const sector = (intern.Sector || "").toLowerCase();
      const createdYear = intern.createdAt
        ? new Date(intern.createdAt).getFullYear().toString()
        : "";

      const matchesSearch =
        `${firstName} ${lastName}`.includes(searchQuery.toLowerCase()) ||
        cff.includes(searchQuery.toLowerCase()) ||
        hometown.includes(searchQuery.toLowerCase()) ||
        email.includes(searchQuery.toLowerCase()) ||
        emplacement.includes(searchQuery.toLowerCase());
      const matchesSector =
        !filterSector || sector === filterSector.toLowerCase();
      const matchesYear = !filterYear || createdYear === filterYear;

      return matchesSearch && matchesSector && matchesYear;
    })
    .sort((a, b) => {
      if (sortField === "Name") {
        const nameA = `${a.First_Name || ""} ${
          a.Last_Name || ""
        }`.toLowerCase();
        const nameB = `${b.First_Name || ""} ${
          b.Last_Name || ""
        }`.toLowerCase();
        return sortDirection === "asc"
          ? nameA.localeCompare(nameB)
          : nameB.localeCompare(nameA);
      }
      const valueA = (a[sortField] || "").toString().toLowerCase();
      const valueB = (b[sortField] || "").toString().toLowerCase();
      return sortDirection === "asc"
        ? valueA.localeCompare(valueB)
        : valueB.localeCompare(valueA);
    });

  const handleExportToExcel = () => {
    const exportData = filteredAndSortedInterns.map((intern) => ({
      CFF: intern.CFF || "",
      Prénom: intern.First_Name || "",
      Nom: intern.Last_Name || "",
      Genre: intern.Gender === "Male" ? "Homme" : "Femme",
      Nationalité: intern.Nationality || "",
      Secteur: intern.Sector || "",
      "Ville d'origine": intern.hometown || "",
      Email: intern.email || "",
      Emplacement: intern.emplacement || "",
      "Numéro de téléphone": intern.phoneNumber || "",
      "Numéro de téléphone des parents": intern.parentPhoneNumber || "",
      "Total Consommation": `${intern.consommation || 0} DH`,
      "Total Paiement": `${intern.totalPayment || 0} DH`,
      "Créé le": intern.createdAt
        ? new Date(intern.createdAt).toLocaleString("fr-FR")
        : "",
      "Mis à jour le": intern.updatedAt
        ? new Date(intern.updatedAt).toLocaleString("fr-FR")
        : "",
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Stagiaires");
    XLSX.writeFile(wb, "Exportation_Stagiaires.xlsx");
    setIsDropdownOpen(false);
  };

  const getSortIcon = (field) => {
    if (sortField !== field) return null;
    return sortDirection === "asc" ? (
      <ChevronUp className="h-4 w-4" />
    ) : (
      <ChevronDown className="h-4 w-4" />
    );
  };

  const uniqueSectors = [
    ...new Set(interns.map((intern) => intern.Sector)),
  ].filter(Boolean);
  const uniqueYears = [
    ...new Set(
      interns.map((intern) =>
        intern.createdAt
          ? new Date(intern.createdAt).getFullYear().toString()
          : ""
      )
    ),
  ]
    .filter(Boolean)
    .sort((a, b) => b - a);

  return (
    <Layout>
      <div className="container mx-auto px-4 py-6">
        {/* Card */}
        <div className="border-none shadow-lg bg-white rounded-xl">
          {/* CardHeader */}
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white rounded-t-xl p-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
              <div>
                <h2 className="text-2xl font-bold tracking-tight">
                  Gestion des Stagiaires
                </h2>
                <p className="text-white mt-1">
                  Afficher et gérer les stagiaires
                </p>
              </div>
              <div className="group relative">
              <button
              onClick={handleCalculateAndResetPayments}
              className="px-4 py-2 bg-white text-[#00717F] rounded-md shadow-sm hover:bg-gray-100 flex items-center gap-2 text-xs sm:text-sm font-medium"
            >
              <DollarSign className="h-4 w-4" />
              Calculer et réinitialiser paiements
            </button>
              </div>
            </div>
          </div>
          {/* CardContent */}
          <div className="p-0">
            <div className="p-4 border-b border-gray-200">
              <div className="flex flex-col md:flex-row gap-4">
                <div className="relative flex-1">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Search className="h-4 w-4 text-gray-400" />
                  </div>
                  <input
                    className="pl-9 w-full border border-gray-300 rounded-md px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500 placeholder-gray-400"
                    placeholder="Rechercher par nom, CFF, ville, email ou emplacement..."
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    aria-label="Rechercher des stagiaires"
                  />
                </div>
                <div className="flex items-center gap-2">
                  <div className="group relative">
                    <button
                      onClick={fetchInterns}
                      className="h-10 w-10 border border-gray-300 rounded-md flex items-center justify-center hover:bg-gray-100 transition-colors"
                      aria-label="Actualiser la liste des stagiaires"
                    >
                      <RefreshCw className="h-4 w-4 text-gray-600" />
                    </button>
                    <span className="absolute hidden group-hover:block bg-gray-800 text-white text-xs rounded-md px-2 py-1 -top-8 left-1/2 transform -translate-x-1/2">
                      Actualiser
                    </span>
                  </div>
                  <div className="relative">
                    <button
                      onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                      className="h-10 w-10 border border-gray-300 rounded-md flex items-center justify-center hover:bg-gray-100 transition-colors"
                      aria-label="Ouvrir le menu des filtres"
                    >
                      <Filter className="h-4 w-4 text-gray-600" />
                    </button>
                    {isDropdownOpen && (
                      <div className="absolute right-0 mt-2 w-48 bg-white border border-gray-200 rounded-md shadow-lg z-10">
                        <button
                          onClick={handleExportToExcel}
                          className="w-full flex items-center gap-2 px-4 py-2 text-sm text-gray-700 hover:bg-gray-100 transition-colors"
                          aria-label="Exporter la liste des stagiaires vers Excel"
                        >
                          <Download className="h-4 w-4" />
                          Exporter vers Excel
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              </div>

              {/* Filters */}
              <div className="mt-4 flex flex-col md:flex-row gap-4">
                <div className="relative flex-1">
                  <select
                    className="w-full border border-gray-300 rounded-md px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500"
                    value={filterSector}
                    onChange={(e) => setFilterSector(e.target.value)}
                    aria-label="Filtrer par secteur"
                  >
                    <option value="">Tous les secteurs</option>
                    {uniqueSectors.map((sector) => (
                      <option key={sector} value={sector}>
                        {sector}
                      </option>
                    ))}
                  </select>
                </div>
                <div className="relative flex-1">
                  <select
                    className="w-full border border-gray-300 rounded-md px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500"
                    value={filterYear}
                    onChange={(e) => setFilterYear(e.target.value)}
                    aria-label="Filtrer par année"
                  >
                    <option value="">Toutes les années</option>
                    {uniqueYears.map((year) => (
                      <option key={year} value={year}>
                        {year}
                      </option>
                    ))}
                  </select>
                </div>
              </div>
            </div>

            {error && (
              <div className="m-4 p-4 bg-red-50 border-l-4 border-red-500 flex items-center gap-3 rounded-md">
                <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0" />
                <p className="text-red-700">{error}</p>
              </div>
            )}

            {isLoading ? (
              <div className="flex justify-center items-center h-64">
                <div className="flex flex-col items-center gap-2">
                  <Loader2 className="h-8 w-8 text-amber-700 animate-spin" />
                  <p className="text-gray-500">Chargement des stagiaires...</p>
                </div>
              </div>
            ) : filteredAndSortedInterns.length === 0 ? (
              <div className="flex flex-col justify-center items-center h-64 text-gray-500">
                <UserCircle className="h-16 w-16 text-gray-300 mb-2" />
                <p className="mb-2">Aucun stagiaire trouvé</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead>
                    <tr className="bg-gray-100 border-b">
                      <th
                        className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleSort("CFF")}
                      >
                        <div className="flex items-center gap-1">
                          CFF {getSortIcon("CFF")}
                        </div>
                      </th>
                      <th
                        className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleSort("Name")}
                      >
                        <div className="flex items-center gap-1">
                          Nom {getSortIcon("Name")}
                        </div>
                      </th>
                      <th
                        className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleSort("Gender")}
                      >
                        <div className="flex items-center gap-1">
                          Genre {getSortIcon("Gender")}
                        </div>
                      </th>
                      <th
                        className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleSort("Nationality")}
                      >
                        <div className="flex items-center gap-1">
                          Nationalité {getSortIcon("Nationality")}
                        </div>
                      </th>
                      <th
                        className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleSort("Sector")}
                      >
                        <div className="flex items-center gap-1">
                          Secteur {getSortIcon("Sector")}
                        </div>
                      </th>
                      <th
                        className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleSort("hometown")}
                      >
                        <div className="flex items-center gap-1">
                          Ville {getSortIcon("hometown")}
                        </div>
                      </th>
                      <th
                        className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleSort("email")}
                      >
                        <div className="flex items-center gap-1">
                          Email {getSortIcon("email")}
                        </div>
                      </th>
                      <th
                        className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleSort("emplacement")}
                      >
                        <div className="flex items-center gap-1">
                          Emplacement {getSortIcon("emplacement")}
                        </div>
                      </th>
                      <th
                        className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleSort("phoneNumber")}
                      >
                        <div className="flex items-center gap-1">
                          Numéro de téléphone {getSortIcon("phoneNumber")}
                        </div>
                      </th>
                      <th
                        className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleSort("parentPhoneNumber")}
                      >
                        <div className="flex items-center gap-1">
                          Numéro de téléphone des parents{" "}
                          {getSortIcon("parentPhoneNumber")}
                        </div>
                      </th>
                      <th
                        className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleSort("consommation")}
                      >
                        <div className="flex items-center gap-1">
                          Total Consommation {getSortIcon("consommation")}
                        </div>
                      </th>
                      <th
                        className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-200 transition-colors"
                        onClick={() => handleSort("totalPayment")}
                      >
                        <div className="flex items-center gap-1">
                          Total Paiement {getSortIcon("totalPayment")}
                        </div>
                      </th>
                      <th className="py-3 px-4 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                        Actions
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y">
                    {filteredAndSortedInterns.map((intern) => (
                      <tr
                        key={intern._id}
                        className="group hover:bg-gray-50 transition-colors cursor-pointer border-l-4 border-l-emerald-400"
                        onClick={() => openDetailsModal(intern)}
                      >
                        <td className="py-4 px-4 text-sm font-medium">
                          {intern.CFF || ""}
                        </td>
                        <td className="py-4 px-4">
                          <div className="flex items-center">
                            <div className="text-sm font-medium">
                              {intern.First_Name || ""} {intern.Last_Name || ""}
                            </div>
                          </div>
                        </td>
                        <td className="py-4 px-4 text-sm text-gray-600">
                          {intern.Gender === "Male" ? "Homme" : "Femme"}
                        </td>
                        <td className="py-4 px-4 text-sm text-gray-600">
                          <div className="flex items-center gap-2">
                            <Flag className="h-4 w-4 text-amber-700/60" />
                            {intern.Nationality || ""}
                          </div>
                        </td>
                        <td className="py-4 px-4 text-sm text-gray-600">
                          <div className="flex items-center gap-2">
                            <Briefcase className="h-4 w-4 text-amber-700/60" />
                            {intern.Sector || ""}
                          </div>
                        </td>
                        <td className="py-4 px-4 text-sm text-gray-600">
                          <div className="flex items-center gap-2">
                            <Home className="h-4 w-4 text-amber-700/60" />
                            {intern.hometown || ""}
                          </div>
                        </td>
                        <td className="py-4 px-4 text-sm text-gray-600">
                          {intern.email || ""}
                        </td>
                        <td className="py-4 px-4 text-sm text-gray-600">
                          <div className="flex items-center gap-2">
                            <MapPin className="h-4 w-4 text-amber-700/60" />
                            {intern.emplacement || ""}
                          </div>
                        </td>
                        <td className="py-4 px-4 text-sm text-gray-600">
                          <div className="flex items-center gap-2">
                            <PhoneIcon className="h-4 w-4 text-amber-700/60" />
                            {intern.phoneNumber || ""}
                          </div>
                        </td>
                        <td className="py-4 px-4 text-sm text-gray-600">
                          <div className="flex items-center gap-2">
                            <PhoneIcon className="h-4 w-4 text-amber-700/60" />
                            {intern.parentPhoneNumber || ""}
                          </div>
                        </td>
                        <td className="py-4 px-4 text-sm text-gray-600">
                          {intern.consommation || 0} DH
                        </td>
                        <td className="py-4 px-4 text-sm text-gray-600">
                          {intern.totalPayment || 0} DH
                        </td>
                        <td className="py-4 px-4 text-sm text-gray-600">
                        <div className="flex items-center gap-2 justify-end">                      
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              openBadgeModal(intern);
                            }}
                            className="px-3 py-1.5 bg-white text-purple-600 rounded-md shadow-sm hover:bg-purple-50 flex items-center gap-1 text-xs sm:text-sm font-medium border border-purple-100"
                            aria-label={`Télécharger le badge de ${intern.First_Name} ${intern.Last_Name}`}
                          >
                            <Download className="h-4 w-4" />
                            <span>Badge</span>
                          </button>

                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              handleRemoveInternToFormer(intern._id, intern.First_Name, intern.Last_Name);
                            }}
                            className="px-3 py-1.5 bg-white text-orange-600 rounded-md shadow-sm hover:bg-orange-50 flex items-center gap-1 text-xs sm:text-sm font-medium border border-orange-100"
                            aria-label={`Retirer ${intern.First_Name} ${intern.Last_Name} vers anciens stagiaires`}
                          >
                            <UserMinus className="h-4 w-4" />
                            <span>Retirer</span>
                          </button>
                        </div>
                      </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Details Modal */}
      {isDetailsModalOpen && selectedIntern && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-lg shadow-xl max-h-[80vh] overflow-y-auto">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold text-[#00717F]">
                Détails du Stagiaire
              </h2>
              <span className="px-2 py-1 bg-emerald-100 text-emerald-800 hover:bg-emerald-200 text-xs font-medium rounded-full">
                Stagiaire
              </span>
            </div>

            <div className="bg-gray-100 p-4 rounded-lg mb-4">
              <div className="flex items-center gap-3 mb-3">
                <div className="h-12 w-12 rounded-full bg-amber-100 flex items-center justify-center text-[#00717F] shadow-sm overflow-hidden">
                  {selectedIntern.image ? (
                    <img
                      src={`${process.env.REACT_APP_API_URL}${selectedIntern.image}`}
                      alt={`${selectedIntern.First_Name} ${selectedIntern.Last_Name}`}
                      className="w-full h-full object-cover"
                    />
                  ) : (
                    <UserCircle className="h-7 w-7" />
                  )}
                </div>
                <div>
                  <h3 className="text-lg font-semibold">
                    {selectedIntern.First_Name || ""}{" "}
                    {selectedIntern.Last_Name || ""}
                  </h3>
                  <p className="text-sm text-gray-500">
                    CFF : {selectedIntern.CFF || ""}
                  </p>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-gray-600">
              <div className="space-y-3 md:border-r md:pr-4">
                <p>
                  <strong className="text-[#00717F]">Genre :</strong>{" "}
                  {selectedIntern.Gender === "Male" ? "Homme" : "Femme"}
                </p>
                <p>
                  <strong className="text-[#00717F]">Nationalité :</strong>{" "}
                  {selectedIntern.Nationality || ""}
                </p>
                <p>
                  <strong className="text-[#00717F]">Secteur :</strong>{" "}
                  {selectedIntern.Sector || ""}
                </p>
                <p>
                  <strong className="text-[#00717F]">Ville d'origine :</strong>{" "}
                  {selectedIntern.hometown || ""}
                </p>
              </div>
              <div className="space-y-3">
                <p>
                  <strong className="text-[#00717F]">Email :</strong>{" "}
                  {selectedIntern.email || ""}
                </p>
                <p>
                  <strong className="text-[#00717F]">Emplacement :</strong>{" "}
                  {selectedIntern.emplacement || ""}
                </p>
                <p>
                  <strong className="text-[#00717F]">
                    Total Consommation :
                  </strong>{" "}
                  {selectedIntern.consommation || 0} DH
                </p>
                <p>
                  <strong className="text-[#00717F]">Total Paiement :</strong>{" "}
                  {selectedIntern.totalPayment || 0} DH
                </p>
              </div>
            </div>

            <div className="flex justify-between items-center gap-2 pt-4 border-t">
              <button
                onClick={openPasswordModal}
                className="flex items-center gap-2 px-4 py-2 bg-gray-200 text-gray-700 rounded-md hover:bg-gray-300 transition-colors"
                aria-label="Réinitialiser le mot de passe du stagiaire"
              >
                <Lock className="h-4 w-4" />
                Réinitialiser le mot de passe
              </button>
              <button
                onClick={closeDetailsModal}
                className="px-4 py-2 bg-[#00717F] text-white rounded-md hover:bg-[#005f6b] transition-colors"
                aria-label="Fermer la fenêtre des détails"
              >
                Fermer
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Password Reset Sub-Modal */}
      {isPasswordModalOpen && selectedIntern && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-md shadow-xl">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-bold text-[#00717F]">
                Réinitialiser le mot de passe
              </h3>
              <button
                onClick={closePasswordModal}
                className="text-gray-500 hover:text-gray-700 transition-colors"
                aria-label="Fermer la fenêtre de réinitialisation du mot de passe"
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            <div className="space-y-4">
              <div className="space-y-2">
                <label
                  className="text-sm font-medium"
                  htmlFor="new-password"
                >
                  Nouveau mot de passe
                </label>
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Lock className="h-4 w-4 text-gray-400" />
                  </div>
                  <input
                    id="new-password"
                    type="password"
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                    className="pl-9 w-full border border-gray-300 rounded-md px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500 placeholder-gray-400"
                    placeholder="Entrez le nouveau mot de passe"
                    aria-label="Nouveau mot de passe"
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label
                  className="text-sm font-medium"
                  htmlFor="confirm-password"
                >
                  Confirmer le mot de passe
                </label>
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Lock className="h-4 w-4 text-gray-400" />
                  </div>
                  <input
                    id="confirm-password"
                    type="password"
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    className="pl-9 w-full border border-gray-300 rounded-md px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500 placeholder-gray-400"
                    placeholder="Confirmez le mot de passe"
                    aria-label="Confirmer le mot de passe"
                  />
                </div>
              </div>
              {passwordError && (
                <div className="p-3 bg-red-50 border-l-4 border-red-500 text-red-700 text-sm rounded-md">
                  {passwordError}
                </div>
              )}
            </div>

            <div className="flex justify-end gap-2 mt-6">
              <button
                onClick={closePasswordModal}
                className="px-4 py-2 bg-gray-200 text-gray-700 rounded-md hover:bg-gray-300 transition-colors"
                aria-label="Annuler la réinitialisation du mot de passe"
              >
                Annuler
              </button>
              <button
                onClick={handleUpdatePassword}
                className="px-4 py-2 bg-emerald-600 text-white rounded-md hover:bg-emerald-700 transition-colors"
                aria-label="Confirmer la réinitialisation du mot de passe"
              >
                Confirmer
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Badge Modal */}
      {isBadgeModalOpen && selectedIntern && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 w-full max-w-2xl shadow-xl max-h-[80vh] overflow-y-auto">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold text-[#00717F]">
                Badge du Stagiaire
              </h2>
              <button
                onClick={closeBadgeModal}
                className="text-gray-500 hover:text-gray-700 transition-colors"
                aria-label="Fermer la fenêtre du badge"
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            <div className="relative w-full max-w-md mx-auto">
              <div className="flex justify-center mb-4 gap-4">
                <button
                  onClick={handleFlip}
                  className="bg-blue-600 hover:bg-blue-700 text-white py-2 px-4 rounded-md transition-colors"
                  aria-label={isFlipped ? "Voir le recto du badge" : "Voir le verso du badge"}
                >
                  {isFlipped ? "Voir le recto" : "Voir le verso"}
                </button>
                <button
                  onClick={handleDownloadBadge}
                  className="bg-green-600 hover:bg-green-700 text-white py-2 px-4 rounded-md transition-colors flex items-center gap-2"
                  aria-label="Télécharger le badge"
                >
                  <Download className="h-4 w-4" />
                  Télécharger
                </button>
              </div>
              <div
                id="badge-container"
                className="relative w-full h-64 perspective-1000"
              >
                <div
                  className={`relative w-full h-full transition-transform duration-700 transform-style-preserve-3d ${
                    isFlipped ? "rotate-y-180" : ""
                  }`}
                >
                  {/* Badge Front */}
                  <div
                    id="badge-front"
                    className={`absolute w-full h-full backface-hidden ${
                      isFlipped ? "invisible" : "visible"
                    }`}
                  >
                    <div className="w-full h-full bg-white rounded-xl shadow-lg overflow-hidden border border-gray-200">
                      <div className="flex flex-col md:flex-row h-full">
                        {/* Left side - Photo */}
                        <div className="w-full md:w-2/5 bg-gray-100 flex items-center justify-center p-0">
                          {selectedIntern.image ? (
                            <img
                              src={`${process.env.REACT_APP_API_URL}${selectedIntern.image}`}
                              alt="Profile"
                              className="w-full h-full object-cover"
                            />
                          ) : (
                            <span className="text-gray-600 text-lg">Photo</span>
                          )}
                        </div>
                        {/* Right side - Information */}
                        <div className="w-full md:w-3/5 p-4 flex flex-col justify-between relative">
                          {/* Background Logo */}
                          <div className="absolute left-11 top-[150px] transform -translate-y-1/2 opacity-80 z-0 flex items-center justify-center w-full">
                            <img
                              src={logo || "/placeholder.svg"}
                              alt="Logo HP ISTA Benguérir"
                              className="w-36 h-36"
                              onError={(e) =>
                                (e.target.src =
                                  "https://placehold.co/200x200/gray/white?text=LOGO+ENTREPRISE")
                              }
                            />
                          </div>

                          {/* Badge header - HP ISTA Benguérir at the top alone */}
                          <div className="text-center mb-3 z-10">
                            <span className="font-semibold text-lg text-[#00717F] tracking-tight">
                              HP ISTA Benguérir
                            </span>
                          </div>

                          <div className="z-10">
                            {/* Name */}
                            <div className="mb-3">
                              <h1 className="text-xl font-bold text-gray-800">
                                {selectedIntern.First_Name}{" "}
                                {selectedIntern.Last_Name}
                              </h1>
                              <p className="text-sm text-red-500">
                                {selectedIntern.email.split("@")[0]}
                              </p>
                            </div>

                            {/* Additional info */}
                            <div className="space-y-1">
                              <div className="flex items-center text-xs">
                                <BuildingIcon
                                  size={14}
                                  className="mr-1 text-gray-600"
                                />
                                <h3 className="text-gray-700">
                                  {selectedIntern.Sector || "Non spécifié"}
                                </h3>
                              </div>
                              <div className="flex items-center text-xs">
                                <MapPinIcon
                                  size={14}
                                  className="mr-1 text-gray-600"
                                />
                                <h3 className="text-gray-700">
                                  {selectedIntern.emplacement || "Non spécifié"}
                                </h3>
                              </div>
                            </div>
                          </div>

                          {/* STAGIAIRE and CFF moved to bottom before footer */}
                          <div className="mt-auto z-10">
                            <div className="mb-2">
                              <h2 className="text-sm font-semibold uppercase text-gray-600">
                                STAGIAIRE
                              </h2>
                              <p className="text-xs text-gray-500">
                                {selectedIntern.CFF}
                              </p>
                            </div>

                            {/* Footer */}
                            <div className="border-t pt-2">
                              <div className="flex items-center text-xs">
                                <CalendarIcon
                                  size={14}
                                  className="mr-1 text-gray-600"
                                />
                                <h3 className="text-gray-600">
                                  Valide jusqu'au :{" "}
                                  {new Date(
                                    selectedIntern.createdAt
                                  ).toLocaleDateString("fr-FR")}
                                </h3>
                              </div>
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Badge Back */}
                  <div
                    id="badge-back"
                    className={`absolute w-full h-full backface-hidden transform rotate-y-180 ${
                      isFlipped ? "visible" : "invisible"
                    }`}
                  >
                    <div className="w-full h-full bg-white rounded-xl shadow-lg overflow-hidden border border-gray-200 flex flex-col">
                      {/* Header */}
                      <div className="bg-blue-600 text-white p-4">
                        <h2 className="text-lg font-bold">
                          Informations du Stagiaire
                        </h2>
                        <p className="text-sm opacity-80">
                          Scannez le code QR pour une vérification numérique
                        </p>
                      </div>
                      {/* QR Code */}
                      <div className="flex-grow flex flex-col items-center justify-center p-4">
                        <div className="bg-white rounded-lg shadow-md">
                          <QRCodeCanvas
                            value={JSON.stringify({
                              id: selectedIntern.CFF,
                              name: `${selectedIntern.First_Name} ${selectedIntern.Last_Name}`,
                              email: selectedIntern.email,
                              sector: selectedIntern.Sector,
                              role: selectedIntern.role || "intern",
                            })}
                            size={150}
                            level={"H"}
                            includeMargin={true}
                          />
                        </div>
                        <p className="mt-3 text-sm text-center text-gray-600">
                          {selectedIntern.CFF}
                        </p>
                      </div>
                      {/* Contact Information */}
                      <div className="bg-gray-100 p-4">
                        <div className="flex flex-col space-y-2">
                          <div className="flex items-center">
                            <MailIcon size={16} className="mr-2 text-gray-600" />
                            <span className="text-sm text-gray-700">
                              {selectedIntern.email}
                            </span>
                          </div>
                          <div className="flex items-center">
                            <PhoneIcon
                              size={16}
                              className="mr-2 text-gray-600"
                            />
                            <span className="text-sm text-gray-700">
                              Contact d'urgence :{" "}
                              {selectedIntern.parentPhoneNumber || "+1 (555) 123-4567"}
                            </span>
                          </div>
                        </div>
                        {/* Company Info */}
                        <div className="mt-4 pt-3 border-t border-gray-300 text-center">
                          <p className="text-xs text-gray-500">
                            En cas de trouvaille, veuillez retourner au siège de
                            l'entreprise
                          </p>
                          <p className="text-xs text-gray-500">
                            123 Avenue Corporative, Quartier des Affaires
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div className="flex justify-end gap-2 mt-6">
              <button
                onClick={closeBadgeModal}
                className="px-4 py-2 bg-gray-200 text-gray-700 rounded-md hover:bg-gray-300 transition-colors"
                aria-label="Fermer la fenêtre du badge"
              >
                Fermer
              </button>
            </div>
          </div>
        </div>
      )}
    </Layout>
